def envelope_dim(gens, n):
    # dim of the associative algebra generated by gens (n x n matrices) incl identity
    basis_vecs = [np.eye(n).ravel()]

    def add(M):
        A = np.array(basis_vecs + [M.ravel()])
        if np.linalg.matrix_rank(A, tol=1e-8) > len(basis_vecs):
            basis_vecs.append(M.ravel())
            return True
        return False

    mats = [np.eye(n)]
    frontier = [np.eye(n)]
    for g in gens:
        if add(g):
            mats.append(g)
            frontier.append(g)
    while frontier and len(basis_vecs) < n * n:
        new = []
        for M in frontier:
            for g in gens:
                P = M @ g
                if add(P):
                    new.append(P)
        frontier = new
    return len(basis_vecs)


